      SUBROUTINE RDNUMB (VALUE, IVALUE, FLAG)CC---- DECODE A REAL NUMBERCC     LIST OF COMMON BLOCKSC      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'NUMREP.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDWRDS.CIN'C-------------------------------------------------------------------CC     LOCAL VARIABLESC      CHARACTER*1     BLANK      CHARACTER*10    NUMRES      LOGICAL         DIG, PNT, EXN, FLAGC      DATA BLANK /' '/      DATA ZERO  /0.0/C-------------------------------------------------------------------C      FLAG = .FALSE.      VALUE = ZERO      IVALUE = 0      NUMREP = BLANK      EXN = .FALSE.CC---- ANY NUMERIC CHARACTER?C      IF (INDEX('0123456789+-.',ITEM) .NE. 0) THEN        ICOLB = ICOL        DIG = .FALSE.        PNT = .FALSE.CC---- SIGN?C        IF (ITEM .EQ. '+' .OR. ITEM .EQ. '-') THEN          CALL RDFWRD        ENDIFCC---- DIGIT OR DECIMAL POINT?C   10   IDIG = INDEX('0123456789',ITEM) - 1        IF (IDIG .GE. 0) THEN          DIG = .TRUE.          CALL RDFWRD          GO TO 10        ELSE IF (ITEM .EQ. '.') THEN          IF (PNT) FLAG = .TRUE.          PNT = .TRUE.          CALL RDFWRD          GO TO 10        ENDIF        FLAG = FLAG .OR. (.NOT. DIG)CC---- EXPONENT?C        IF (INDEX('DE',ITEM) .NE. 0) THEN          CALL RDFWRD          DIG = .FALSE.          EXN = .TRUE.          IF (ITEM .EQ. '+' .OR. ITEM .EQ. '-') THEN            CALL RDFWRD          ENDIF   20     IDIG = INDEX('0123456789',ITEM) - 1          IF (IDIG .GE. 0) THEN            DIG = .TRUE.            CALL RDFWRD            GO TO 20          ENDIF          FLAG = FLAG .OR. (.NOT. DIG)   30     IF (INDEX('0123456789.DE',ITEM) .NE. 0) THEN            CALL RDSKIP('0123456789.DE')            IF (ENDFIL) GO TO 50            FLAG = .TRUE.          ENDIF        ENDIFCC---- RETURN VALUEC        IF (FLAG) THEN          CALL RDFAIL          WRITE (NOUT,910)          FLUSHL = .TRUE.        ELSE          CALL RDBACK          ICOLS = 80 - ICOL + ICOLB          ICOLT = ICOL - ICOLB + 1          NUMREP(ICOLS:80) = KTEXT(ICOLB:ICOL)          READ (NUMREP,930) VALUE          NUMRES = ' '          DO 40 J = 2, 10          JP70 = J + 70          NUMRES(J:J) = NUMREP(JP70:JP70)   40     CONTINUE          IF (.NOT. PNT .AND. .NOT. EXN) READ (NUMRES,950) IVALUE        ENDIF      ELSE        CALL RDFAIL        WRITE (NOUT,920)        FLAG = .TRUE.      ENDIF   50 CONTINUE      RETURNC-------------------------------------------------------------------  910 FORMAT(' *** ERROR *** INCORRECT REAL VALUE'/' ')  920 FORMAT(' *** ERROR *** REAL VALUE EXPECTED'/' ')  930 FORMAT (E80.0)  940 FORMAT (I80)  950 FORMAT (I10)C-------------------------------------------------------------------      END